// ci/eval_gate.ts -- the gate runner invoked in the deploy pipeline
async function runEvalGate(serviceConfig: GateConfig, candidate: ModelOrPromptRef) {
  const baseline = await loadBaselineScores(serviceConfig.eval_suite, serviceConfig.baseline_model);
  const candidateScores = await runEvalSuite(serviceConfig.eval_suite, candidate);
  const result = compareWithSignificance(baseline, candidateScores, {
    metric: serviceConfig.regression_threshold.metric,
    minSampleSize: serviceConfig.regression_threshold.min_sample_size,
  });
  if (result.regressed && result.pctDrop > serviceConfig.regression_threshold.max_drop_pct) {
    if (serviceConfig.blocking) {
      await notify(serviceConfig.escalation_channel, result);
      throw new DeployBlockedError(`Eval regression: ${result.pctDrop}% drop, p=${result.pValue}`);
    }
    await notify(serviceConfig.escalation_channel, { ...result, blocking: false });
  }
  await recordGateRun(serviceConfig.service, candidate, result);
  return result;
}

