class KillSwitchService:
    def __init__(self, store: KillSwitchStore, cache_ttl_s=2):
        self.store = store  # backed by a fast, highly-available KV store (e.g. Redis/DynamoDB)
        self.cache_ttl_s = cache_ttl_s
        self._local_cache = {}

    def is_halted(self, scope: str) -> bool:
        # scope examples: 'global', 'agent:claims-adjuster-v3', 'class:customer-facing'
        cached = self._local_cache.get(scope)
        if cached and cached.fresh():
            return cached.value
        value = self.store.get(f'killswitch:{scope}') or False
        self._local_cache[scope] = CachedValue(value, ttl=self.cache_ttl_s)
        return value

    def trip(self, scope: str, reason: str, actor: str):
        self.store.set(f'killswitch:{scope}', True)
        audit_log.write(event='killswitch_tripped', scope=scope, reason=reason, actor=actor)
        self.store.publish('killswitch_events', {'scope': scope, 'state': True})

    def reset(self, scope: str, actor: str, requires_second_approver: bool = True):
        if requires_second_approver and not self.has_second_approval(scope):
            raise ApprovalRequiredError(scope)
        self.store.set(f'killswitch:{scope}', False)
        audit_log.write(event='killswitch_reset', scope=scope, actor=actor)

