class TenantScopedRetriever:
    def __init__(self, vector_client, tenant_id: str):
        if not tenant_id:
            raise ValueError('TenantScopedRetriever requires a non-empty tenant_id')
        self._tenant_id = tenant_id
        self._client = vector_client
        # No method on this class accepts a tenant_id parameter from the caller --
        # the tenant is bound once, at construction, and used internally on every call.

    def search(self, query_embedding, top_k=10, extra_filter: dict | None = None):
        filter_clause = {'tenant_id': self._tenant_id}
        if extra_filter:
            if 'tenant_id' in extra_filter:
                raise SecurityError('Callers may not override tenant_id in extra_filter')
            filter_clause.update(extra_filter)
        results = self._client.query(
            vector=query_embedding,
            filter=filter_clause,
            top_k=top_k,
        )
        # Defense in depth: verify every returned result's stored tenant_id
        # actually matches, rather than trusting the filter alone.
        for r in results:
            if r.metadata.get('tenant_id') != self._tenant_id:
                audit_log.write(event='tenant_isolation_violation_blocked',
                                 tenant=self._tenant_id, leaked_doc_tenant=r.metadata.get('tenant_id'))
                raise TenantIsolationError('Post-query verification failed; result discarded')
        return results

