class InjectionTestCase:
    def __init__(self, name, payload_fn, detection_fn, category, severity):
        self.name = name
        self.payload_fn = payload_fn      # builds the adversarial input/context for this run
        self.detection_fn = detection_fn  # inspects agent behavior/output for a successful bypass
        self.category = category          # e.g. 'direct_injection', 'indirect_via_retrieval', 'multi_turn_escalation'
        self.severity = severity

def run_redteam_suite(agent_under_test, test_cases: list[InjectionTestCase]):
    results = []
    for tc in test_cases:
        payload = tc.payload_fn()
        transcript = agent_under_test.run(payload)
        bypassed = tc.detection_fn(transcript)
        results.append(RedTeamResult(
            test=tc.name, category=tc.category, severity=tc.severity,
            bypassed=bypassed, transcript_ref=store_transcript(transcript),
        ))
    return results

