class StagedRollout:
    STAGES = [1, 5, 25, 50, 100]  # percent of traffic on the candidate model

    def __init__(self, candidate_model, baseline_model, health_checks, stage_duration_s=300):
        self.candidate = candidate_model
        self.baseline = baseline_model
        self.health_checks = health_checks  # e.g. error_rate, judge_score_mean, latency_p99, escalation_rate
        self.stage_duration_s = stage_duration_s
        self.current_stage_idx = 0

    def advance(self):
        set_traffic_split(self.candidate, pct=self.STAGES[self.current_stage_idx])
        stage_start = now()
        while now() - stage_start < self.stage_duration_s:
            sleep(10)
            for check in self.health_checks:
                result = check.evaluate(window_s=60, model=self.candidate)
                if result.breached:
                    return self.rollback(reason=result)
        self.current_stage_idx += 1
        if self.current_stage_idx >= len(self.STAGES):
            audit_log.write(event='rollout_complete', model=self.candidate.id)
            return RolloutStatus.COMPLETE
        return RolloutStatus.ADVANCING

    def rollback(self, reason):
        set_traffic_split(self.candidate, pct=0)
        set_traffic_split(self.baseline, pct=100)
        audit_log.write(event='auto_rollback', model=self.candidate.id, reason=reason, stage=self.current_stage_idx)
        notify('#deploy-alerts', f'Auto-rollback triggered at stage {self.STAGES[self.current_stage_idx]}%: {reason}')
        return RolloutStatus.ROLLED_BACK

