class AgentSecretsProvider:
    def __init__(self, vault_client, agent_identity: str):
        self._vault = vault_client
        self._agent_identity = agent_identity  # scoped per-agent, never a shared platform-wide key

    def get_tool_credential(self, tool_name: str, requested_scope: str) -> ScopedCredential:
        policy = policy_store.get_allowed_scopes(self._agent_identity, tool_name)
        if requested_scope not in policy.allowed_scopes:
            audit_log.write(event='credential_scope_denied', agent=self._agent_identity,
                             tool=tool_name, requested=requested_scope)
            raise ScopeDeniedError(tool_name, requested_scope)
        cred = self._vault.issue_short_lived(
            principal=self._agent_identity, resource=tool_name,
            scope=requested_scope, ttl_s=policy.max_ttl_s,
        )
        audit_log.write(event='credential_issued', agent=self._agent_identity,
                         tool=tool_name, scope=requested_scope, ttl_s=policy.max_ttl_s)
        return cred  # never logged, never returned in the agent's own context/transcript

