class PerConsumerLimiter:
    def __init__(self, store, default_rps=50, default_concurrency=20):
        self.store = store  # fast shared counter store, e.g. Redis with TTL-based sliding window
        self.default_rps = default_rps
        self.default_concurrency = default_concurrency

    def check_and_reserve(self, consumer_id: str):
        limits = limit_registry.get(consumer_id, rps=self.default_rps, concurrency=self.default_concurrency)
        if not self.store.sliding_window_allow(f'rps:{consumer_id}', limits.rps):
            raise RateLimitExceeded(consumer_id, limit_type='rps')
        if not self.store.increment_if_below(f'concurrency:{consumer_id}', limits.concurrency):
            raise RateLimitExceeded(consumer_id, limit_type='concurrency')
        return ReservationToken(consumer_id)

    def release(self, token: ReservationToken):
        self.store.decrement(f'concurrency:{token.consumer_id}')

class UpstreamCircuitBreaker:
    def __init__(self, failure_threshold=0.5, window_s=30, cooldown_s=60):
        self.failure_threshold = failure_threshold
        self.window_s = window_s
        self.cooldown_s = cooldown_s
        self.state = 'closed'
        self.opened_at = None

    def call(self, fn, *args):
        if self.state == 'open':
            if now() - self.opened_at > self.cooldown_s:
                self.state = 'half_open'
            else:
                raise CircuitOpenError()
        try:
            result = fn(*args)
            self.record_success()
            if self.state == 'half_open':
                self.state = 'closed'
            return result
        except UpstreamError:
            self.record_failure()
            if self.failure_rate(self.window_s) > self.failure_threshold:
                self.state = 'open'
                self.opened_at = now()
            raise

