import numpy as np
from scipy import stats

def evaluate_golden_set(candidate_fn, golden_examples):
    scores = [score_example(candidate_fn, ex) for ex in golden_examples]
    return np.array(scores)

def compare_with_significance(baseline_scores, candidate_scores, min_detectable_effect=0.03, alpha=0.05):
    n = len(baseline_scores)
    if n < required_sample_size(min_detectable_effect, alpha, power=0.8, baseline_std=baseline_scores.std()):
        return RegressionResult(verdict='INSUFFICIENT_POWER', n=n)
    t_stat, p_value = stats.ttest_rel(candidate_scores, baseline_scores)
    mean_diff = candidate_scores.mean() - baseline_scores.mean()
    ci_low, ci_high = bootstrap_ci(candidate_scores - baseline_scores, n_boot=5000)
    verdict = 'REGRESSION' if (p_value < alpha and mean_diff < 0) else \
              'IMPROVEMENT' if (p_value < alpha and mean_diff > 0) else 'NO_SIGNIFICANT_CHANGE'
    return RegressionResult(verdict=verdict, p_value=p_value, mean_diff=mean_diff,
                             ci=(ci_low, ci_high), n=n)

def ship_decision(result: RegressionResult):
    if result.verdict == 'REGRESSION':
        return 'BLOCK'
    if result.verdict == 'INSUFFICIENT_POWER':
        return 'BLOCK'  # cannot approve a claim the data can't actually support
    return 'APPROVE'

