class PromptTemplate:
    def __init__(self, template_id, version, body, variables, created_by, eval_suite_ref):
        self.template_id = template_id
        self.version = version          # immutable once published -- never edited in place
        self.body = body
        self.variables = variables
        self.created_by = created_by
        self.eval_suite_ref = eval_suite_ref
        self.consumers = set()          # populated via explicit pin, not inferred

class TemplateRegistry:
    def publish(self, template_id, body, variables, author, eval_suite_ref):
        new_version = next_version(template_id)
        candidate = PromptTemplate(template_id, new_version, body, variables, author, eval_suite_ref)
        eval_result = run_eval_suite(eval_suite_ref, candidate)
        if eval_result.has_regressions():
            raise PublishBlockedError(eval_result)
        self._store.write(candidate)  # new immutable version, old versions untouched
        return new_version

    def resolve(self, template_id, consumer_id):
        pin = pin_registry.get(consumer_id, template_id)
        if pin is None:
            raise UnpinnedConsumerError(consumer_id, template_id)  # no implicit 'latest'
        return self._store.read(template_id, pin.version)

    def deprecate(self, template_id, version, sunset_date):
        affected = pin_registry.find_consumers_pinned_to(template_id, version)
        notify_all(affected, f'{template_id} v{version} sunsetting {sunset_date}')
        deprecation_schedule.register(template_id, version, sunset_date)

