class RedactionResult:
    def __init__(self, redacted_text, entities_found, original_hash):
        self.redacted_text = redacted_text
        self.entities_found = entities_found  # [(type, span, confidence)]
        self.original_hash = original_hash    # allows re-identification only via a separate, access-controlled lookup

def redact_before_ingestion(raw_chunk_text: str) -> RedactionResult:
    entities = pii_detector.detect(raw_chunk_text)  # NER model + regex/pattern rules (phone, account#, SSN-like)
    redacted = raw_chunk_text
    for entity in sorted(entities, key=lambda e: e.span[0], reverse=True):
        placeholder = f'[{entity.type}_{entity.id}]'
        redacted = redacted[:entity.span[0]] + placeholder + redacted[entity.span[1]:]
        if entity.type in REVERSIBLE_TYPES:
            secure_vault.store_mapping(entity.id, entity.original_value)  # access-controlled, separate store
    return RedactionResult(redacted_text=redacted, entities_found=entities, original_hash=hash(raw_chunk_text))

def ingest_chunk(raw_chunk_text, metadata):
    result = redact_before_ingestion(raw_chunk_text)
    if result.entities_found and not confidence_above_threshold(result.entities_found):
        quarantine_queue.add(raw_chunk_text, metadata, reason='low_confidence_pii_review_needed')
        return
    embedding = embed(result.redacted_text)  # the embedding is computed from REDACTED text, never raw
    vector_store.upsert(embedding, text=result.redacted_text, metadata=metadata)
